import{_ as d,o as e,c as p,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/CROSSTABS.md","filePath":"manual-zh/CROSSTABS.md","lastUpdated":1785684581000}'),r={name:"manual-zh/CROSSTABS.md"};function c(a,t,s,n,i,S){return e(),p("div",null,[...t[0]||(t[0]=[o(`<h3 id="_15-6-crosstabs" tabindex="-1">15.6 CROSSTABS <a class="header-anchor" href="#_15-6-crosstabs" aria-label="Permalink to &quot;15.6 CROSSTABS&quot;">​</a></h3><pre><code>CROSSTABS
        /TABLES=var_list BY var_list [BY var_list]…
        /MISSING={TABLE,INCLUDE,REPORT}
        /FORMAT={TABLES,NOTABLES}
                {AVALUE,DVALUE}
        /CELLS={COUNT,ROW,COLUMN,TOTAL,EXPECTED,RESIDUAL,SRESIDUAL,
                ASRESIDUAL,ALL,NONE}
        /COUNT={ASIS,CASE,CELL}
               {ROUND,TRUNCATE}
        /STATISTICS={CHISQ,PHI,CC,LAMBDA,UC,BTAU,CTAU,RISK,GAMMA,D,
                     KAPPA,ETA,CORR,ALL,NONE}
        /BARCHART

(Integer mode.)
        /VARIABLES=var_list (low,high)…
</code></pre><p><code>CROSSTABS</code> 过程显示用户所请求的列联表。它可以为列联表中的每个单元格计算若干统计量。此外，还可以为每个表本身计算若干统计量。</p><p><code>TABLES</code> 子命令用于指定要报告的表。允许任意维度数，每个维度也允许任意数量的变量。<code>TABLES</code> 子命令可根据需要重复多次。这是 <em>general mode</em>（通用模式）下唯一必需的子命令。</p><p>有时，可能希望调用一种称为 <em>integer mode</em>（整数模式）的特殊模式。通常，在通用模式下，PSPP 自动确定数据中出现了哪些值。在整数模式下，用户指定数据所取值的范围。要调用此模式，需指定 <code>VARIABLES</code> 子命令，为 <code>TABLES</code> 子命令中要使用的每个变量给出括号内的数据值范围。范围内的数据值会被截断为最接近的整数，然后赋给该值。若出现范围之外的值，则将它们丢弃。当使用该子命令时，<code>VARIABLES</code> 必须位于 <code>TABLES</code> 子命令之前。</p><p>在通用模式下，<code>TABLES</code> 上可指定数值变量和字符串变量。在整数模式下，只允许数值变量。</p><p><code>MISSING</code> 子命令决定对用户缺失值的处理方式。设为默认值 <code>TABLE</code> 时，缺失值按表逐个丢弃。设为 <code>INCLUDE</code> 时，用户缺失值被纳入表和统计。设为 <code>REPORT</code> 时（仅允许在整数模式下），用户缺失值被纳入表，但会标注脚注，并排除在统计计算之外。</p><p><code>FORMAT</code> 子命令控制要显示的列联表的特征。它有多种可选设置：</p><ul><li><code>TABLES</code>（默认）会使列联表被输出。<code>NOTABLES</code>（等价于 <code>CELLS=NONE</code>）则抑制其输出。</li><li><code>AVALUE</code>（默认）使取值按升序排序。<code>DVALUE</code> 表示降序排序。</li></ul><p><code>CELLS</code> 子命令控制所显示的列联表中每个单元格的内容。可选设置如下：</p><p>COUNT</p><p>频数。</p><p>ROW</p><p>行百分比。</p><p>COLUMN</p><p>列百分比。</p><p>TOTAL</p><p>表百分比。</p><p>EXPECTED</p><p>期望值。</p><p>RESIDUAL</p><p>残差。</p><p>SRESIDUAL</p><p>标准化残差。</p><p>ASRESIDUAL</p><p>调整标准化残差。</p><p>ALL</p><p>以上全部。</p><p>NONE</p><p>完全抑制单元格。</p><p>未指定任何设置的 ‘/CELLS’ 会请求 <code>COUNT</code>、<code>ROW</code>、<code>COLUMN</code> 和 <code>TOTAL</code>。如果完全未指定 <code>CELLS</code>，则只选择 <code>COUNT</code>。</p><p>默认情况下，列联表和统计使用原始个案权重，不四舍五入。使用 <code>/COUNT</code> 子命令进行取整：CASE 在读取个案时对各个权重取整，CELL 在列联表构建完成后对其中各单元格的权重取整，ASIS 显式指定默认的不取整行为。请求取整时，默认 ROUND 按最接近的整数取整，TRUNCATE 向零取整。</p><p><code>STATISTICS</code> 子命令选择要计算的统计量：</p><p>CHISQ</p><p>皮尔逊卡方、似然比、费歇尔精确检验、连续性校正、线性-by-线性关联。</p><p>PHI</p><p>Phi 系数。</p><p>CC</p><p>列联系数。</p><p>LAMBDA</p><p>Lambda。</p><p>UC</p><p>不确定系数。</p><p>BTAU</p><p>Tau-b。</p><p>CTAU</p><p>Tau-c。</p><p>RISK</p><p>风险估计。</p><p>GAMMA</p><p>Gamma。</p><p>D</p><p>Somers’ D。</p><p>KAPPA</p><p>Cohen’s Kappa。</p><p>ETA</p><p>Eta。</p><p>CORR</p><p>斯皮尔曼相关、皮尔逊 r。</p><p>ALL</p><p>以上全部。</p><p>NONE</p><p>无统计量。</p><p>所选统计量仅在适用时才计算。某些统计量要求特定大小的表，有些统计量仅在整数模式下计算。</p><p>未指定任何设置的 ‘/STATISTICS’ 会选择 CHISQ。如果未给出 <code>STATISTICS</code> 子命令，则不计算任何统计量。</p><p>‘/BARCHART’ 子命令为每个表的前两个变量生成簇状条形图。如果表的变量超过两个，则第三个及后续层级的计数会被聚合，图表会像只有两个变量一样生成。</p><p><strong>请注意：</strong> 当前 <code>CROSSTABS</code> 的实现存在以下限制：</p><ul><li>某些方向性度量的显著性未计算。</li><li>未计算 Goodman 和 Kruskal 的 tau 或对称 Somers’ d 的渐近标准误。</li><li>未计算对称不确定系数的近似 T。</li></ul><p>欢迎修复上述任何缺陷。</p><h4 id="_15-6-1-列联表示例" tabindex="-1">15.6.1 列联表示例 <a class="header-anchor" href="#_15-6-1-列联表示例" aria-label="Permalink to &quot;15.6.1 列联表示例&quot;">​</a></h4><p>一位研究者希望了解在某行业中，个人的性别是否与其职业相关。为了调查这一点，她确认 personnel.sav 是一个具有代表性的、随机选取的人员样本。该研究者的零假设是：个人的性别与其职业无关。她使用卡方独立性检验来研究该假设。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file=&quot;personnel.sav&quot;.  crosstabs 	/tables= occupation by sex 	/cells = count expected 	/statistics=chisq.</span></span></code></pre></div><p><strong>示例 15.3：</strong> 对 <strong>sex</strong> 和 <strong>occupation</strong> 变量运行列联表</p><p>示例 15.3 中的语法执行了卡方独立性检验。行 <code>/tables = occupation by sex</code> 表示 <strong>occupation</strong> 和 <strong>sex</strong> 是要制表的变量。要使用图形用户界面完成此操作，必须将这些变量名分别放入“Row”（行）和“Column”（列）字段，如截图 15.3 所示。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div><p><strong>截图 15.3：</strong> 已选择 <strong>sex</strong> 和 <strong>occupation</strong> 变量的列联表对话框</p><p>类似地，“Cells”（单元格）按钮会显示一个对话框，用于选择 <code>count</code> 和 <code>expected</code> 选项。对于此检验，可以取消选择所有其他单元格选项。</p><p>可使用“Format”（格式）和“Statistics”（统计）按钮为 <code>FORMAT</code> 和 <code>STATISTICS</code> 子命令选择选项。在本例中，“Statistics”只需勾选“Chisq”选项。其他所有选项都应取消勾选。“Format”对话框不需要特殊设置。</p><p>如结果 15.1 所示，<code>CROSSTABS</code> 生成一个列联表，其中包含每个性别和每个职业的观测频数和期望频数。期望频数是在零假设成立时本应观测到的频数。</p><p>Pearson 卡方值的显著性远大于通常接受的 0.05，因此无法拒绝零假设。于是研究者只能得出：个人的性别与其职业无关。</p><table tabindex="0"><thead><tr><th></th><th>N</th><th>Percent</th><th>N</th><th>Percent</th><th>N</th><th>Percent</th></tr></thead><tbody><tr><td></td><td>Cases</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>Valid</td><td>Missing</td><td>Total</td><td></td><td></td><td></td></tr><tr><td>occupation × sex</td><td>54</td><td>96.4%</td><td>2</td><td>3.6%</td><td>56</td><td>100.0%</td></tr><tr><td></td><td></td><td></td><td>sex</td><td>Total</td><td></td><td></td></tr><tr><td></td><td></td><td></td><td>Male</td><td>Female</td><td></td><td></td></tr><tr><td>occupation</td><td>Artist</td><td>Count</td><td>2</td><td>6</td><td>8</td><td></td></tr><tr><td>Expected</td><td>4.89</td><td>3.11</td><td>.15</td><td></td><td></td><td></td></tr><tr><td>Baker</td><td>Count</td><td>1</td><td>1</td><td>2</td><td></td><td></td></tr><tr><td>Expected</td><td>1.22</td><td>.78</td><td>.04</td><td></td><td></td><td></td></tr><tr><td>Barrister</td><td>Count</td><td>0</td><td>1</td><td>1</td><td></td><td></td></tr><tr><td>Expected</td><td>.61</td><td>.39</td><td>.02</td><td></td><td></td><td></td></tr><tr><td>Carpenter</td><td>Count</td><td>3</td><td>1</td><td>4</td><td></td><td></td></tr><tr><td>Expected</td><td>2.44</td><td>1.56</td><td>.07</td><td></td><td></td><td></td></tr><tr><td>Cleaner</td><td>Count</td><td>4</td><td>0</td><td>4</td><td></td><td></td></tr><tr><td>Expected</td><td>2.44</td><td>1.56</td><td>.07</td><td></td><td></td><td></td></tr><tr><td>Cook</td><td>Count</td><td>3</td><td>2</td><td>5</td><td></td><td></td></tr><tr><td>Expected</td><td>3.06</td><td>1.94</td><td>.09</td><td></td><td></td><td></td></tr><tr><td>Manager</td><td>Count</td><td>4</td><td>4</td><td>8</td><td></td><td></td></tr><tr><td>Expected</td><td>4.89</td><td>3.11</td><td>.15</td><td></td><td></td><td></td></tr><tr><td>Mathematician</td><td>Count</td><td>3</td><td>1</td><td>4</td><td></td><td></td></tr><tr><td>Expected</td><td>2.44</td><td>1.56</td><td>.07</td><td></td><td></td><td></td></tr><tr><td>Painter</td><td>Count</td><td>1</td><td>1</td><td>2</td><td></td><td></td></tr><tr><td>Expected</td><td>1.22</td><td>.78</td><td>.04</td><td></td><td></td><td></td></tr><tr><td>Payload Specialist</td><td>Count</td><td>1</td><td>0</td><td>1</td><td></td><td></td></tr><tr><td>Expected</td><td>.61</td><td>.39</td><td>.02</td><td></td><td></td><td></td></tr><tr><td>Plumber</td><td>Count</td><td>5</td><td>0</td><td>5</td><td></td><td></td></tr><tr><td>Expected</td><td>3.06</td><td>1.94</td><td>.09</td><td></td><td></td><td></td></tr><tr><td>Scientist</td><td>Count</td><td>5</td><td>2</td><td>7</td><td></td><td></td></tr><tr><td>Expected</td><td>4.28</td><td>2.72</td><td>.13</td><td></td><td></td><td></td></tr><tr><td>Scrientist</td><td>Count</td><td>0</td><td>1</td><td>1</td><td></td><td></td></tr><tr><td>Expected</td><td>.61</td><td>.39</td><td>.02</td><td></td><td></td><td></td></tr><tr><td>Tailor</td><td>Count</td><td>1</td><td>1</td><td>2</td><td></td><td></td></tr><tr><td>Expected</td><td>1.22</td><td>.78</td><td>.04</td><td></td><td></td><td></td></tr><tr><td>Total</td><td>Count</td><td>33</td><td>21</td><td>54</td><td></td><td></td></tr><tr><td>Expected</td><td>.61</td><td>.39</td><td>1.00</td><td></td><td></td><td></td></tr><tr><td></td><td>Value</td><td>df</td><td>Asymptotic Sig. (2-tailed)</td><td></td><td></td><td></td></tr><tr><td>Pearson Chi-Square</td><td>15.59</td><td>13</td><td>.272</td><td></td><td></td><td></td></tr><tr><td>Likelihood Ratio</td><td>19.66</td><td>13</td><td>.104</td><td></td><td></td><td></td></tr><tr><td>N of Valid Cases</td><td>54</td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>结果 15.1：</strong> <strong>sex</strong> 与 <strong>occupation</strong> 之间独立性的检验结果</p>`,82)])])}const C=d(r,[["render",c]]);export{l as __pageData,C as default};
